<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { ArrowDown, ArrowUp, CopyDocument, Delete, EditPen, Plus, Setting } from '@element-plus/icons-vue'
import { genreModuleApi, sectionApi } from '../api'
import { useGenresStore } from '../stores/genres'
import type { FieldDefinition, FieldType, GenreModule, ModuleSection } from '../types'

const store = useGenresStore()
const modules = computed(() => store.allModules.filter((item) => !item.deleted_at).sort((a,b) => a.sort_order-b.sort_order))
const selectedId = ref('')
const sections = ref<ModuleSection[]>([])
const loadingSections = ref(false)
const moduleDialog = ref(false)
const editingModule = ref<GenreModule|null>(null)
const moduleForm = reactive({ name:'',slug:'',icon:'Collection',description:'',theme_color:'#f59e0b',sort_order:0,status:'active' as 'active'|'disabled'|'archived',visible:true,profile_json:{ core_audience:'18—35岁内容用户',hot_tags:[] as string[],positioning:'',heat:75,trend:'stable' },create_default_sections:true })
const sectionDialog = ref(false)
const editingSection = ref<ModuleSection|null>(null)
const sectionForm = reactive<{section_key:string;section_name:string;icon:string;sort_order:number;enabled:boolean;field_schema:FieldDefinition[]}>({section_key:'',section_name:'',icon:'Document',sort_order:0,enabled:true,field_schema:[]})
const fieldTypes: Array<{value:FieldType;label:string}> = [{value:'text',label:'单行文本'},{value:'textarea',label:'多行文本'},{value:'markdown',label:'Markdown'},{value:'number',label:'数字'},{value:'date',label:'日期'},{value:'select',label:'单选'},{value:'multiselect',label:'多选'},{value:'tags',label:'标签'},{value:'image',label:'图片链接'},{value:'url',label:'网址'},{value:'relation',label:'关联素材'}]
const selectedModule = computed(() => modules.value.find((item) => item.id === selectedId.value) || null)

onMounted(async () => { await store.fetchAllModules(); selectedId.value = modules.value[0]?.id || ''; if(selectedId.value) await loadSections() })
async function refreshModules() { await Promise.all([store.fetchAllModules(),store.fetchModules()]) }
async function selectModule(id:string){selectedId.value=id;await loadSections()}
async function loadSections(){if(!selectedId.value)return;loadingSections.value=true;try{sections.value=(await genreModuleApi.sections(selectedId.value,true)).data.data}catch{sections.value=[]}finally{loadingSections.value=false}}

function openModule(item?:GenreModule){editingModule.value=item||null;if(item){Object.assign(moduleForm,{name:item.name,slug:item.slug,icon:item.icon,description:item.description,theme_color:item.theme_color,sort_order:item.sort_order,status:item.status,visible:item.visible,profile_json:JSON.parse(JSON.stringify(item.profile_json)),create_default_sections:false})}else{Object.assign(moduleForm,{name:'',slug:'',icon:'Collection',description:'',theme_color:'#f59e0b',sort_order:modules.value.length,status:'active',visible:true,profile_json:{core_audience:'18—35岁内容用户',hot_tags:[],positioning:'',heat:75,trend:'stable'},create_default_sections:true})}moduleDialog.value=true}
async function saveModule(){if(!moduleForm.name.trim()||!moduleForm.slug.trim())return ElMessage.warning('名称和 slug 必填');if(editingModule.value)await genreModuleApi.update(editingModule.value.id,moduleForm);else await genreModuleApi.create(moduleForm);ElMessage.success(editingModule.value?'模块配置已更新':'模块已创建，左侧导航和独立路由已自动生成');moduleDialog.value=false;await refreshModules();if(!editingModule.value){selectedId.value=modules.value.find((item)=>item.slug===moduleForm.slug)?.id||selectedId.value;await loadSections()}}
async function toggleModule(item:GenreModule){if(item.status==='active')await genreModuleApi.disable(item.id);else await genreModuleApi.enable(item.id);ElMessage.success(item.status==='active'?'模块已停用，数据完整保留':'模块已启用并显示在导航');await refreshModules()}
async function duplicateModule(item:GenreModule){const result=await genreModuleApi.duplicate(item.id);ElMessage.success(`已复制为“${result.data.data.name}”`);await refreshModules()}
async function archiveModule(item:GenreModule){await ElMessageBox.confirm(`归档“${item.name}”？模块会从导航隐藏，但其中素材不会删除。`,'归档题材模块',{type:'warning'});await genreModuleApi.archive(item.id);ElMessage.success('模块已归档，内部数据完整保留');if(selectedId.value===item.id)selectedId.value='';await refreshModules()}
async function moveModule(index:number,direction:-1|1){const list=[...modules.value];const target=index+direction;if(target<0||target>=list.length)return;[list[index],list[target]]=[list[target]!,list[index]!];await genreModuleApi.reorder(list.map((item,i)=>({id:item.id,sort_order:i})));await refreshModules()}

function openSection(item?:ModuleSection){editingSection.value=item||null;if(item)Object.assign(sectionForm,{section_key:item.section_key,section_name:item.section_name,icon:item.icon,sort_order:item.sort_order,enabled:item.enabled,field_schema:JSON.parse(JSON.stringify(item.field_schema))});else Object.assign(sectionForm,{section_key:'custom_section',section_name:'自定义板块',icon:'Document',sort_order:sections.value.length,enabled:true,field_schema:[]});sectionDialog.value=true}
function addField(){sectionForm.field_schema.push({key:`field_${sectionForm.field_schema.length+1}`,label:'新字段',type:'text',required:false,options:[],placeholder:''})}
async function saveSection(){if(!selectedId.value)return;if(editingSection.value)await sectionApi.update(editingSection.value.id,sectionForm);else await genreModuleApi.createSection(selectedId.value,{...sectionForm,filter_schema:{},card_schema:{}});ElMessage.success(editingSection.value?'板块配置已更新':'功能板块已创建');sectionDialog.value=false;await loadSections();await refreshModules()}
async function toggleSection(item:ModuleSection){await sectionApi.update(item.id,{enabled:!item.enabled});ElMessage.success(item.enabled?'板块已停用，素材仍保留':'板块已启用');await loadSections()}
async function removeSection(item:ModuleSection){await ElMessageBox.confirm(`删除“${item.section_name}”？仅无素材的板块可以删除。`,'删除功能板块',{type:'warning'});await sectionApi.remove(item.id);ElMessage.success('功能板块已删除');await loadSections();await refreshModules()}
async function moveSection(index:number,direction:-1|1){const list=[...sections.value];const target=index+direction;if(target<0||target>=list.length)return;[list[index],list[target]]=[list[target]!,list[index]!];await sectionApi.reorder(list.map((item,i)=>({id:item.id,sort_order:i})));await loadSections()}
</script>

<template>
  <div class="settings-page">
    <div class="page-heading"><div><span>CONFIGURATION CENTER</span><h1>模块设置</h1><p>题材、导航、板块顺序和动态表单都由数据库配置驱动。</p></div><el-button type="primary" :icon="Plus" @click="openModule()">新增题材模块</el-button></div>
    <div class="settings-grid">
      <section class="module-list surface"><header><div><h2>题材模块</h2><span>{{ modules.length }} 个配置</span></div><el-icon><Setting /></el-icon></header><div class="module-rows"><div v-for="(item,index) in modules" :key="item.id" class="module-row" :class="{active:selectedId===item.id}" @click="selectModule(item.id)"><span class="color" :style="{background:item.theme_color}"></span><div><b>{{ item.name }}</b><small>/genres/{{ item.slug }} · {{ item.material_count }} 条素材</small></div><em :class="item.status">{{ item.status==='active'?'启用':item.status==='disabled'?'停用':'归档' }}</em><div class="row-actions" @click.stop><button :disabled="index===0" @click="moveModule(index,-1)"><el-icon><ArrowUp /></el-icon></button><button :disabled="index===modules.length-1" @click="moveModule(index,1)"><el-icon><ArrowDown /></el-icon></button><el-dropdown trigger="click"><button><span>•••</span></button><template #dropdown><el-dropdown-menu><el-dropdown-item :icon="EditPen" @click="openModule(item)">编辑模块</el-dropdown-item><el-dropdown-item @click="toggleModule(item)">{{ item.status==='active'?'停用模块':'启用模块' }}</el-dropdown-item><el-dropdown-item :icon="CopyDocument" @click="duplicateModule(item)">复制配置</el-dropdown-item><el-dropdown-item :icon="Delete" divided @click="archiveModule(item)">归档模块</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></div></div></section>
      <section class="section-settings surface"><header v-if="selectedModule"><div><span class="header-color" :style="{background:selectedModule.theme_color}"></span><div><h2>{{ selectedModule.name }} · 功能板块</h2><p>可开启、关闭、排序、重命名，并定义素材自定义字段。</p></div></div><el-button :icon="Plus" @click="openSection()">新增板块</el-button></header><div v-if="!selectedModule" class="no-select">请从左侧选择一个题材模块</div><div v-else v-loading="loadingSections" class="section-list"><div class="section-head"><span>板块</span><span>字段结构</span><span>状态</span><span>素材</span><span>排序与操作</span></div><div v-for="(item,index) in sections" :key="item.id" class="section-row"><div><span class="section-index">{{ String(index+1).padStart(2,'0') }}</span><div><b>{{ item.section_name }}</b><small>{{ item.section_key }}</small></div></div><div class="schema-tags"><span v-for="field in item.field_schema.slice(0,3)" :key="field.key">{{ field.label }} · {{ field.type }}</span><i v-if="item.field_schema.length>3">+{{ item.field_schema.length-3 }}</i><em v-if="!item.field_schema.length">公共字段</em></div><el-switch :model-value="item.enabled" @change="toggleSection(item)" /><span class="count">{{ item.material_count }}</span><div class="section-actions"><el-button-group><el-button :icon="ArrowUp" :disabled="index===0" @click="moveSection(index,-1)" /><el-button :icon="ArrowDown" :disabled="index===sections.length-1" @click="moveSection(index,1)" /></el-button-group><el-button text :icon="EditPen" @click="openSection(item)">配置</el-button><el-button v-if="!item.material_count" text :icon="Delete" @click="removeSection(item)" /></div></div></div></section>
    </div>

    <el-dialog v-model="moduleDialog" :title="editingModule?'编辑题材模块':'新增题材模块'" width="700px"><div class="dialog-grid"><el-form-item label="模块名称" required><el-input v-model="moduleForm.name" placeholder="例如：职场悬疑" /></el-form-item><el-form-item label="独立路由 slug" required><el-input v-model="moduleForm.slug" placeholder="workplace-mystery"><template #prepend>/genres/</template></el-input></el-form-item><el-form-item label="图标名称"><el-input v-model="moduleForm.icon" placeholder="Collection" /></el-form-item><el-form-item label="主题颜色"><el-color-picker v-model="moduleForm.theme_color" /><el-input v-model="moduleForm.theme_color" class="color-input" /></el-form-item><el-form-item label="核心受众"><el-input v-model="moduleForm.profile_json.core_audience" /></el-form-item><el-form-item label="热门标签"><el-select v-model="moduleForm.profile_json.hot_tags" multiple filterable allow-create class="w-full" /></el-form-item><el-form-item label="热度指数"><el-input-number v-model="moduleForm.profile_json.heat" :min="0" :max="100" class="w-full" /></el-form-item><el-form-item label="趋势"><el-select v-model="moduleForm.profile_json.trend" class="w-full"><el-option label="上升" value="rising" /><el-option label="稳定" value="stable" /></el-select></el-form-item><el-form-item label="模块介绍" class="wide"><el-input v-model="moduleForm.description" type="textarea" :rows="3" /></el-form-item><el-form-item label="画像说明" class="wide"><el-input v-model="moduleForm.profile_json.positioning" type="textarea" :rows="2" /></el-form-item><el-form-item v-if="!editingModule" label="自动生成默认板块"><el-switch v-model="moduleForm.create_default_sections" /></el-form-item></div><template #footer><el-button @click="moduleDialog=false">取消</el-button><el-button type="primary" @click="saveModule">保存模块</el-button></template></el-dialog>

    <el-dialog v-model="sectionDialog" :title="editingSection?'配置功能板块':'新增功能板块'" width="860px"><div class="dialog-grid section-base"><el-form-item label="板块名称"><el-input v-model="sectionForm.section_name" /></el-form-item><el-form-item label="板块标识"><el-input v-model="sectionForm.section_key" :disabled="Boolean(editingSection)" /></el-form-item><el-form-item label="图标"><el-input v-model="sectionForm.icon" /></el-form-item><el-form-item label="启用"><el-switch v-model="sectionForm.enabled" /></el-form-item></div><div class="field-builder"><header><div><h3>动态字段结构</h3><p>新增素材时，前端会严格按这里的 field_schema 生成表单。</p></div><el-button :icon="Plus" @click="addField">添加字段</el-button></header><div v-if="!sectionForm.field_schema.length" class="no-fields">当前仅使用标题、概述、正文、状态和标签等公共字段。</div><div v-for="(field,index) in sectionForm.field_schema" :key="index" class="field-row"><span>{{ index+1 }}</span><el-input v-model="field.label" placeholder="字段名称" /><el-input v-model="field.key" placeholder="field_key" /><el-select v-model="field.type"><el-option v-for="type in fieldTypes" :key="type.value" :label="type.label" :value="type.value" /></el-select><el-input v-if="['select','multiselect'].includes(field.type)" :model-value="field.options.join(',')" placeholder="选项，逗号分隔" @update:model-value="field.options=$event.split(',').filter(Boolean)" /><el-input v-else v-model="field.placeholder" placeholder="占位提示" /><el-checkbox v-model="field.required">必填</el-checkbox><button @click="sectionForm.field_schema.splice(index,1)">×</button></div></div><template #footer><el-button @click="sectionDialog=false">取消</el-button><el-button type="primary" @click="saveSection">保存板块配置</el-button></template></el-dialog>
  </div>
</template>

<style scoped>
.settings-page{max-width:1500px;margin:0 auto;padding:28px 30px 50px}.page-heading{display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:20px}.page-heading span{color:var(--accent);font-size:8px;font-weight:800;letter-spacing:.16em}.page-heading h1{margin:5px 0 4px;font-family:"Songti SC",serif;font-size:27px}.page-heading p{margin:0;color:var(--text-muted);font-size:11px}.settings-grid{display:grid;grid-template-columns:360px 1fr;gap:12px;align-items:start}.module-list,.section-settings{border-radius:10px;overflow:hidden}.module-list>header,.section-settings>header{min-height:62px;display:flex;align-items:center;justify-content:space-between;padding:13px 15px;border-bottom:1px solid var(--border-soft)}.module-list h2,.section-settings h2{margin:0;font-size:13px}.module-list header span,.section-settings header p{margin:4px 0 0;color:var(--text-muted);font-size:9px}.module-list header>.el-icon{color:var(--accent)}.module-rows{max-height:calc(100vh - 190px);overflow-y:auto;padding:6px}.module-row{display:grid;grid-template-columns:7px 1fr auto auto;align-items:center;gap:9px;padding:10px 8px;border-radius:7px;cursor:pointer}.module-row:hover{background:var(--panel-raised)}.module-row.active{background:var(--accent-soft)}.module-row .color{width:7px;height:28px;border-radius:4px}.module-row b,.module-row small{display:block}.module-row b{font-size:11px}.module-row small{margin-top:3px;color:var(--text-muted);font-size:8px}.module-row>em{padding:2px 5px;border-radius:4px;background:var(--panel-hover);color:var(--text-muted);font-size:8px;font-style:normal}.module-row>em.active{background:rgba(52,211,153,.1);color:#34d399}.row-actions{display:flex}.row-actions button{width:25px;height:25px;display:grid;place-items:center;border:0;border-radius:4px;background:transparent;color:var(--text-muted);cursor:pointer}.row-actions button:hover{background:var(--panel-hover);color:var(--text)}.header-color{width:7px;height:34px;border-radius:4px}.section-settings>header>div{display:flex;align-items:center;gap:10px}.section-list{min-height:500px}.section-head,.section-row{display:grid;grid-template-columns:minmax(150px,1.1fr) minmax(220px,1.6fr) 70px 50px 190px;align-items:center;gap:12px;padding:10px 15px}.section-head{background:var(--bg-soft);color:var(--text-muted);font-size:8px;font-weight:700}.section-row{min-height:58px;border-top:1px solid var(--border-soft)}.section-row>div:first-child{display:flex;align-items:center;gap:9px}.section-index{color:var(--text-muted);font:9px monospace}.section-row b,.section-row small{display:block}.section-row b{font-size:10px}.section-row small{margin-top:3px;color:var(--text-muted);font-size:8px}.schema-tags{display:flex;flex-wrap:wrap;gap:4px}.schema-tags span,.schema-tags i{padding:3px 5px;border-radius:4px;background:rgba(59,130,246,.08);color:#81aef1;font-size:7px;font-style:normal}.schema-tags em{color:var(--text-muted);font-size:8px;font-style:normal}.count{color:var(--text-secondary);font-size:10px}.section-actions{display:flex;align-items:center;justify-content:flex-end}.no-select,.no-fields{display:grid;place-items:center;min-height:300px;color:var(--text-muted);font-size:10px}.dialog-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 14px}.dialog-grid .wide{grid-column:1/-1}.color-input{width:130px;margin-left:8px}.w-full{width:100%}.field-builder{margin-top:15px;border-top:1px solid var(--border-soft);padding-top:15px}.field-builder>header{display:flex;align-items:center;justify-content:space-between;margin-bottom:10px}.field-builder h3{margin:0;font-size:12px}.field-builder p{margin:4px 0 0;color:var(--text-muted);font-size:8px}.no-fields{min-height:90px;border:1px dashed var(--border);border-radius:7px}.field-row{display:grid;grid-template-columns:24px 1fr 1fr 130px 1.1fr 58px 26px;align-items:center;gap:7px;padding:7px 0;border-top:1px solid var(--border-soft)}.field-row>span{color:var(--text-muted);font:9px monospace}.field-row>button{border:0;background:transparent;color:var(--text-muted);cursor:pointer;font-size:16px}.field-row>button:hover{color:var(--danger)}@media(max-width:1200px){.settings-grid{grid-template-columns:300px 1fr}.section-head,.section-row{grid-template-columns:140px 1fr 55px 40px 150px}}
</style>
